from ta_messaging.message_types_utils import all_messages_in_protocol

supported_protocols = ['rrc', 's1ap']


rrc_from_ta_messaging = dict(zip(all_messages_in_protocol('rrc', name_from_3gpp=False),
                                 all_messages_in_protocol('rrc', name_from_3gpp=True)))

s1ap_from_ta_messaging = dict(zip(all_messages_in_protocol('s1ap', name_from_3gpp=False),
                                  all_messages_in_protocol('s1ap', name_from_3gpp=True)))

rrc = dict(map(lambda item: (item[0].replace('-r13', 'NB'), item[1]) if '-r13' in item[0] else (item[0], item[1]),
               rrc_from_ta_messaging.items()))

rrc.update(
    {'rrcConnectionReconfiguration-HO-InterCell': 'RRCConnectionReconfiguration',
     'rrcConnectionReconfiguration-HO-InterENB': 'RRCConnectionReconfiguration',
     'rrcConnectionReconfiguration-HO-IntraCell': 'RRCConnectionReconfiguration',
     'mbmsInterestIndication': 'MBMSInterestIndication-r11',
     'interFreqRSTDMeasurementIndication': 'InterFreqRSTDMeasurementIndication-r10',
     'ulDedicatedMessageSegment': 'ULDedicatedMessageSegment-r16',
     'sidelinkUEInformationR12': 'SidelinkUEInformation-r12',
     'inDeviceCoexIndication': 'InDeviceCoexIndication-r11'})

message_types = {}
message_types.update(rrc)
message_types.update(s1ap_from_ta_messaging)
